// Wraps the base64 model bundles (generated by prepare-models.js) into
// bravojs's module.declare() format and writes a package.dcp manifest for
// each, ready to publish to the DCP package manager. Publishing raw
// `module.exports = {...}` breaks on a real worker (see
// docs.dcp.dev's "Publishing a DCP package" -- whole-object module.exports
// reassignment silently fails inside module.declare() factories) -- so each
// file's top-level keys are assigned onto `exports` individually instead,
// keeping the published module's shape identical to the existing
// {filename: base64} map every loader module already expects.
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const PKG_DIR = path.join(ROOT, 'packages');

// Each package's published filename must be globally distinct across every
// package a job might require() together -- DCP's sandbox require() takes
// just the bare filename (`require('file.js')`, no package prefix), so its
// module namespace is flat by basename across a whole job's job.requires()
// list, not scoped per-package. Four packages all named "model.js" would
// collide the moment one job needed more than one of them.
const MODELS = [
  { bundle: 'pyannoteModelFilesBase64', pkgName: 'callrag-pyannote-seg3-fp32', version: '1.0.1', fileName: 'pyannote-model.js' },
  { bundle: 'bgeSmallModelFilesBase64', pkgName: 'callrag-bge-small-en-q8', version: '1.0.1', fileName: 'bge-model.js' },
  { bundle: 'whisperBaseEnModelFilesBase64', pkgName: 'callrag-whisper-base-en-uint8', version: '1.0.1', fileName: 'whisper-model.js' },
  { bundle: 'wavlmModelFilesBase64', pkgName: 'callrag-wavlm-base-sv-q8', version: '1.0.1', fileName: 'wavlm-model.js' },
];

function buildOne({ bundle, pkgName, version, fileName }) {
  const data = require(path.join(ROOT, bundle));
  const outDir = path.join(PKG_DIR, pkgName);
  fs.mkdirSync(outDir, { recursive: true });

  const modelJsPath = path.join(outDir, fileName);
  const assignments = Object.entries(data)
    .map(([k, v]) => `exports[${JSON.stringify(k)}] = ${JSON.stringify(v)};`)
    .join('\n  ');
  const wrapped = `module.declare([], function (require, exports, module) {\n  ${assignments}\n});\n`;
  fs.writeFileSync(modelJsPath, wrapped);

  const manifest = { name: pkgName, version, files: { [fileName]: fileName } };
  const manifestPath = path.join(outDir, 'package.dcp');
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n');

  const size = fs.statSync(modelJsPath).size;
  console.log(`built ${pkgName}@${version}: ${(size / 1024 / 1024).toFixed(1)}MB -> ${manifestPath}`);
}

for (const model of MODELS) buildOne(model);
console.log('\nAll packages built. Run scripts/publish-model-packages.js to publish.');
